From e6293eb3d120f48d39ce33cf6b5eb9cbc6c5ee22 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:13:51 +0100
Subject: [PATCH] scripting: restore a serialized panel on its saved screen

loadSerializedLayout() created every panel through addPanel(), which
puts it on the active screen, so a saved global theme brought all of its
panels back on one screen. Move each panel to its saved lastScreen first.

BUG: 514584
---
 shell/scripting/scriptengine_v1.cpp | 7 +++++++
 1 file changed, 7 insertions(+)

diff --git a/shell/scripting/scriptengine_v1.cpp b/shell/scripting/scriptengine_v1.cpp
index f99d1eeabd..1632ad561b 100644
--- a/shell/scripting/scriptengine_v1.cpp
+++ b/shell/scripting/scriptengine_v1.cpp
@@ -390,6 +390,13 @@ QJSValue ScriptEngine::V1::loadSerializedLayout(const QJSValue &data)

         Q_ASSERT(panel);

+        // Put the panel back on its saved screen if that screen is connected
+        bool hasScreen = false;
+        const int screen = panelData.property(u"config"_s).property(u"/"_s).property(u"lastScreen"_s).toVariant().toInt(&hasScreen);
+        if (hasScreen && static_cast<ShellCorona *>(m_engine->m_corona)->screenPool()->screenForId(screen)) {
+            panel->setScreen(screen);
+        }
+
         // Basic panel setup
         panel->setLocation(panelData.property(u"location"_s).toString());
         panel->setHeight(panelData.property(u"height"_s).toNumber() * gridUnit());
